const item = $input.first().json;
const output = item.output ?? '';

const separator = '---JSON---';
const parts = output.split(separator);

let mensagem = output.trim();
let estadoAtualizado = null;

if (parts.length >= 3) {
  mensagem = parts[0].trim();
  const jsonStr = parts[1].trim();
  try {
    estadoAtualizado = JSON.parse(jsonStr);
  } catch(e) {
    // fallback: tenta extrair JSON com regex
    const match = parts[1].match(/\{[\s\S]*\}/);
    if (match) {
      try { estadoAtualizado = JSON.parse(match[0]); } catch(e2) {}
    }
  }
}

const estadoAnterior = $('Parse do estado').item.json.estado;

// Merge profundo: preserva campos já coletados
const estadoFinal = estadoAtualizado ? {
  ...estadoAnterior,
  currentStep: estadoAtualizado.currentStep ?? estadoAnterior.currentStep,
  isCompleted: estadoAtualizado.isCompleted ?? false,
  answers: {
    mood:           estadoAtualizado.mood           ?? estadoAnterior.answers?.mood           ?? null,
    completedTasks: estadoAtualizado.completedTasks ?? estadoAnterior.answers?.completedTasks ?? [],
    rest:           estadoAtualizado.rest           ?? estadoAnterior.answers?.rest           ?? null,
    bottleneck:     estadoAtualizado.bottleneck     ?? estadoAnterior.answers?.bottleneck     ?? null,
    gratitude:      estadoAtualizado.gratitude      ?? estadoAnterior.answers?.gratitude      ?? null
  },
  // Campos extras do JSON do prompt original
  totalTasks:           estadoAtualizado.totalTasks           ?? estadoAnterior.totalTasks           ?? 0,
  completedTasksCount:  estadoAtualizado.completedTasksCount  ?? estadoAnterior.completedTasksCount  ?? 0,
  completionRateDaily:  estadoAtualizado.completionRateDaily  ?? estadoAnterior.completionRateDaily  ?? 0,
  botFinalMessage:      estadoAtualizado.botFinalMessage      ?? estadoAnterior.botFinalMessage      ?? null
} : estadoAnterior;

return [{
  json: {
    phone:        $('Parse do estado').item.json.phone,
    evo_url:      $('Parse do estado').item.json.evo_url,
    evo_instance: $('Parse do estado').item.json.evo_instance,
    evo_api_key:  $('Parse do estado').item.json.evo_api_key,
    userName:     $('Parse do estado').item.json.userName,
    mensagem:     mensagem,
    estadoFinal:  estadoFinal,
    isCompleted:  estadoFinal.isCompleted ?? false,
    // Passa o JSON completo do agente para salvar no Firestore
    checkinPayload: estadoAtualizado
  }
}];

const item = $input.first().json;
const estado = item.estadoFinal;
const payload = item.checkinPayload ?? {};
const a = estado.answers ?? {};
const totalTasks = payload.totalTasks ?? (estado.dailyTasks ?? []).length;
const completedCount = payload.completedTasksCount ?? (a.completedTasks ?? []).length;

// Usa o JSON completo retornado pelo agente como base
// e complementa com campos que o agente pode não ter preenchido
const checkinDoc = {
  userId:              payload.userId              ?? estado.userId ?? item.phone,
  userName:            payload.userName            ?? estado.userName ?? item.userName,
  date:                payload.date                ?? estado.date ?? new Date().toISOString().split('T')[0],
  currentStep:         'closing',
  isCompleted:         true,
  mood:                payload.mood                ?? a.mood ?? null,
  completedTasks:      payload.completedTasks      ?? a.completedTasks ?? [],
  totalTasks:          totalTasks,
  completedTasksCount: completedCount,
  completionRateDaily: totalTasks > 0 ? completedCount / totalTasks : 0,
  rest:                payload.rest                ?? a.rest ?? null,
  bottleneck:          payload.bottleneck          ?? a.bottleneck ?? null,
  gratitude:           payload.gratitude           ?? a.gratitude ?? null,
  botFinalMessage:     payload.botFinalMessage      ?? item.mensagem ?? null,
  source:              'whatsapp',
  createdAt:           new Date().toISOString()
};

return [{ json: { ...item, checkinDoc } }];

const entrada = $('Entrada do sub-workflow').first()?.json ?? {};
const redisRaw = $input.first()?.json ?? {};

// Redis pode retornar o valor em propriedades diferentes dependendo da versão
const raw = redisRaw.estado ?? redisRaw.value ?? redisRaw.data ?? null;

let estado;
try {
  estado = typeof raw === 'string' ? JSON.parse(raw) : (raw ?? {});
} catch(e) {
  estado = {};
}

// Garante estrutura mínima caso Redis esteja vazio ou chave não exista
if (!estado || typeof estado !== 'object') {
  estado = {};
}

estado.currentStep  = estado.currentStep  ?? 'start';
estado.answers      = estado.answers      ?? {};
estado.dailyTasks   = estado.dailyTasks   ?? [];
estado.isCompleted  = estado.isCompleted  ?? false;
estado.userId       = estado.userId       ?? entrada.phone ?? '';
estado.userName     = estado.userName     ?? entrada.userName ?? 'Estudante';
estado.date         = estado.date         ?? new Date().toISOString().split('T')[0];

return [{
  json: {
    phone:              entrada.phone        ?? '',
    userMessage:        entrada.userMessage  ?? '',
    userName:           entrada.userName     ?? estado.userName,
    evo_url:            entrada.evo_url      ?? '',
    evo_instance:       entrada.evo_instance ?? '',
    evo_api_key:        entrada.evo_api_key  ?? '',
    estado:             estado,
    // Campos flat para o system prompt
    userId:             estado.userId,
    date:               estado.date,
    dailyTasksStr:      JSON.stringify(estado.dailyTasks),
    currentStep:        estado.currentStep,
    currentAnswersStr:  JSON.stringify(estado.answers)
  }
}];
